    async def set_auto_reject(
        self,
        domain_name: str,
        body: TransferAutoRejectDto,
        *,
        options: RequestOptions | None = None,
    ) -> TransferAutoRejectSetResponseDto:
        """Turn transfer auto-reject on or off

        Sets auto-reject at the registry and then stores it in LETO. When on, the registry rejects transfer
        requests from other registrars automatically, and transfer requests from other LETO accounts are
        refused. This is the way to block outgoing transfers in advance for registries that do not let you
        approve or reject them. Turning it off is refused for domains that use local presence.

        Body fields:
        - `transferAutoReject` (required): true to reject incoming transfer requests automatically, false to
          turn it off.

        Errors (LetoApiError, branch on error_code):
        - 400: `DOMAIN_INVALID_STATUS`: the domain is not active. `DOMAIN_UPDATE_LOCKED`: the update lock is
          on. Turn it off first. `TRANSFER_AUTO_REJECT_SET_FAILED`: the registry refused the change, for
          example because the TLD does not support it. `data.reason` carries the registry message.
          `VALIDATION_FAILED`: the field is missing or is not a JSON boolean. Strings such as "false" and
          numbers are rejected. Nothing was changed.
        - 403: `OPERATION_NOT_ALLOWED`: the registry connection for this TLD has no auto-reject setting.
        - 404: `DOMAIN_NOT_FOUND`: the domain is not in your account. `DOMAIN_NOT_REGISTERED`: the domain
          has no registry registration yet.
        - 409: `OPERATION_NOT_ALLOWED`: turning auto-reject off is not allowed while the domain uses local
          presence.
        - 410: `DOMAIN_EXPIRED`: the domain has expired.

        HTTP: `PUT /api/v1/domain/{domainName}/transferautoreject`

        Args:
            domain_name: Domain name in your account.
            body: Request body (fields listed above).
            options: Retries and extra headers for this call.

        Returns:
            TransferAutoRejectSetResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "PUT",
            "/api/v1/domain/{domainName}/transferautoreject",
            path_params={"domainName": domain_name},
            body=body,
            options=options,
        )
        return cast(TransferAutoRejectSetResponseDto, response)
